from decimal import Decimal, ROUND_HALF_UP


class Cart:
    _CENTS = Decimal("0.01")

    def __init__(self, tax_rate: str | Decimal = "0") -> None:
        rate = Decimal(tax_rate) if isinstance(tax_rate, str) else tax_rate
        if not (Decimal("0") <= rate <= Decimal("1")):
            raise ValueError("tax_rate must be between 0 and 1 inclusive")
        self._tax_rate: Decimal = rate
        self._items: dict[str, tuple[Decimal, int]] = {}  # sku -> (price, qty)
        self._coupon: str | None = None

    def add_item(self, sku: str, price: str | Decimal, qty: int = 1) -> None:
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            raise ValueError("qty must be an int >= 1")
        unit_price = Decimal(price) if isinstance(price, str) else price
        if unit_price < 0:
            raise ValueError("price must be >= 0")
        if sku in self._items:
            existing_price, existing_qty = self._items[sku]
            if unit_price != existing_price:
                raise ValueError(
                    "price differs from price already in cart for this SKU"
                )
            self._items[sku] = (existing_price, existing_qty + qty)
        else:
            self._items[sku] = (unit_price, qty)

    def remove_item(self, sku: str, qty: int | None = None) -> None:
        if sku not in self._items:
            raise KeyError(sku)
        if qty is None:
            del self._items[sku]
            return
        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
            raise ValueError("qty must be >= 1")
        _, current_qty = self._items[sku]
        if qty > current_qty:
            raise ValueError("qty exceeds quantity in cart")
        remaining = current_qty - qty
        if remaining == 0:
            del self._items[sku]
        else:
            self._items[sku] = (self._items[sku][0], remaining)

    def apply_coupon(self, code: str) -> None:
        if code not in ("SAVE10", "FIVEOFF"):
            raise ValueError(f"Invalid coupon code: {code}")
        self._coupon = code

    def item_count(self) -> int:
        return sum(qty for _, qty in self._items.values())

    def summary(self) -> dict[str, Decimal]:
        subtotal = Decimal("0")
        for price, qty in self._items.values():
            subtotal += price * qty
        subtotal = subtotal.quantize(self._CENTS, rounding=ROUND_HALF_UP)

        discount = Decimal("0")
        if self._coupon == "SAVE10":
            discount = subtotal * Decimal("0.10")
        elif self._coupon == "FIVEOFF":
            discount = Decimal("5.00")
            if discount > subtotal:
                discount = subtotal
        discount = discount.quantize(self._CENTS, rounding=ROUND_HALF_UP)

        taxable = subtotal - discount
        tax = (taxable * self._tax_rate).quantize(self._CENTS, rounding=ROUND_HALF_UP)

        total = (subtotal - discount + tax).quantize(self._CENTS, rounding=ROUND_HALF_UP)

        return {
            "subtotal": subtotal,
            "discount": discount,
            "tax": tax,
            "total": total,
        }
